import{_ as n,a0 as r,w as s,s as h,ao as c,I as l,x as t,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Echo命令实例 | LCTT x X-CMD","titleTemplate":false,"description":"Echo命令实例 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Echo命令实例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Echo命令实例 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140811 Echo Command with Practical Examples","title":"Echo命令实例","tag":"201408","desc":""},"relativePath":"201408/20140811 Echo Command with Practical Examples.md","filePath":"[post].md"}'),p={name:"201408/20140811 Echo Command with Practical Examples.md"};function m(d,e,u,x,b,f){const i=r("Link");return s(),h("div",null,[e[11]||(e[11]=c(`<h1 id="echo命令实例" tabindex="-1">Echo命令实例 <a class="header-anchor" href="#echo命令实例" aria-label="Permalink to “Echo命令实例”">​</a></h1><p>echo命令是内建的<strong>shell命令</strong>，用于显示<strong>变量</strong>的值或者<strong>打印一行文本</strong>。</p><p>echo命令在构建shell脚本时扮演着重要的角色。</p><h3 id="语法" tabindex="-1">语法： <a class="header-anchor" href="#语法" aria-label="Permalink to “语法：”">​</a></h3><pre><code># echo [Options] [String]
</code></pre><p>方括号中的项目是可选的。字符串可以定义为字符的有限序列（如字母，数字，符号，标点符号）。</p><p>当echo命令不带任何选项或字符串使用时，它会在显示屏上返回一个空白行，后面换一行跟上命令提示符。这是因为按下回车键就是发送一个信号给系统以开始一个新行，而echo重复了该信号。</p><h3 id="选项" tabindex="-1">选项： <a class="header-anchor" href="#选项" aria-label="Permalink to “选项：”">​</a></h3><ul><li>-n 不要输出衍生的新行</li><li>-e 启用反斜线转义解释</li><li>-E 禁用反斜线转义解释（默认）</li></ul><p>如果使用-e选项，则可以使用如下转义序列：</p><ul><li>\\ 反斜线</li><li>\\a 警告（BEL）</li><li>\\b 反斜线</li><li>\\c 不产生进一步输出</li><li>\\e 转义</li><li>\\f 换页</li><li>\\n 新行</li><li>\\r 换行字符</li><li>\\t 水平制表</li><li>\\v 垂直制表</li><li>\\0NNN 八进制值表示的字节NNN（1到3个数字）</li><li>\\xHH 十六进制值表示的字节NNN（1到2个数字）</li></ul><h3 id="样例-1-显示系统定义的变量的值" tabindex="-1">样例：1 显示系统定义的变量的值 <a class="header-anchor" href="#样例-1-显示系统定义的变量的值" aria-label="Permalink to “样例：1  显示系统定义的变量的值”">​</a></h3><p>使用set命令，我们可以列出系统定义的变量。而要打印这些变量的值，我们可以使用echo命令：</p><pre><code>jack@localhost:~$ echo $USER
jack
jack@localhost:~$ echo $HOME
/home/jack
</code></pre><h3 id="样例-2-显示用户定义的变量的值" tabindex="-1">样例：2 显示用户定义的变量的值 <a class="header-anchor" href="#样例-2-显示用户定义的变量的值" aria-label="Permalink to “样例：2 显示用户定义的变量的值”">​</a></h3><pre><code>jack@nextstep4it:~$ var1=\`date\`
jack@nextstep4it:~$ echo &quot;Today&#39;s date  time is : $var1&quot;
Today&#39;s date  time is : Mon Jul 28 13:11:37 IST 2014
</code></pre><h3 id="样例-3-显示文本字符串" tabindex="-1">样例：3 显示文本字符串 <a class="header-anchor" href="#样例-3-显示文本字符串" aria-label="Permalink to “样例：3 显示文本字符串”">​</a></h3><pre><code>jack@nextstep4it:~$ echo &quot; Hi this echo command testing&quot;
Hi this echo command testing
</code></pre><h3 id="样例-4-在echo命令中使用反斜线" tabindex="-1">样例：4 在echo命令中使用反斜线 <a class="header-anchor" href="#样例-4-在echo命令中使用反斜线" aria-label="Permalink to “样例：4 在echo命令中使用反斜线”">​</a></h3><pre><code>jack@nextstep4it:~$ echo -e &quot;Ubuntu \\bis \\bthe \\bbest \\bDesktop \\bOS&quot;
</code></pre><p>上述命令将打印：</p><p>UbuntuisthebestDesktopOS</p><h3 id="样例-5-在echo命令中使用制表符空格" tabindex="-1">样例：5 在echo命令中使用制表符空格 <a class="header-anchor" href="#样例-5-在echo命令中使用制表符空格" aria-label="Permalink to “样例：5  在echo命令中使用制表符空格”">​</a></h3><pre><code>nextstep4it@nextstep4it:~$ echo -e &quot;Ubuntu \\tis \\tthe \\tbest \\tDesktop \\tOS&quot;
</code></pre><p>上述命令将显示如下输出：</p><p>Ubuntu is the best Desktop OS</p><h3 id="样例-6-在echo命令中使用垂直制表符" tabindex="-1">样例：6 在echo命令中使用垂直制表符 <a class="header-anchor" href="#样例-6-在echo命令中使用垂直制表符" aria-label="Permalink to “样例：6 在echo命令中使用垂直制表符”">​</a></h3><pre><code>jack@nextstep4it:~$ echo -e &quot;Ubuntu \\vis \\vthe \\vbest \\vDesktop \\vOS&quot;
Ubuntu
       is
              the
                     best
                            Desktop
                                          OS
</code></pre><h3 id="样例-7-设置echo命令彩色输出" tabindex="-1">样例：7 设置echo命令彩色输出 <a class="header-anchor" href="#样例-7-设置echo命令彩色输出" aria-label="Permalink to “样例：7  设置echo命令彩色输出”">​</a></h3><p>echo命令可以修改字体类型，字体背景色以及字体颜色，转义序列\\033可以用于改变字体属性。要使转义序列生效，必须使用-e选项。下面列出了部分转义代码：</p><ul><li>[0m: 正常</li><li>[1m: 粗体</li><li>[4m: 字体加上下划线</li><li>[7m: 逆转前景和背景色</li><li>[8m: 不可见字符</li><li>[9m: 跨行字体</li><li>[30m: 灰色字体</li><li>[31m: 红色字体</li><li>[32m: 绿色字体</li><li>[33m: 棕色字体</li><li>[34m: 蓝色字体</li><li>[35m: 紫色字体</li><li>[36m: 浅蓝色字体</li><li>[37m: 浅灰字体</li><li>[38m: 黑色字体</li><li>[40m: 黑色背景</li><li>[41m: 红色背景</li><li>[42m: 绿色背景</li><li>[43m: 棕色背景</li><li>[44m: 蓝色背景</li><li>[45m: 紫色背景</li><li>[46m: 浅蓝色背景</li><li>[47m: 浅灰色背景</li></ul><p>下面的命令将用红色打印输出。</p><pre><code>jack@nextstep4it:~$ echo -e &quot;\\033[31mMagic of Linux\\033[0m&quot;
Magic of Linux
</code></pre><p>下面的命令将以粗体以及红色背景打印出“Magic of Linux”。</p><pre><code>nextstep4it@nextstep4it:~$ echo -e &quot;\\033[1m\\033[41mMagic of Linux\\033[0m&quot;
Magic of Linux
</code></pre><hr>`,36)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),a(i,{href:"http://www.nextstep4it.com/categories/unix-command/echo-command/"},{default:o(()=>[...e[0]||(e[0]=[t("http://www.nextstep4it.com/categories/unix-command/echo-command/",-1)])]),_:1})]),l("p",null,[e[4]||(e[4]=t("译者：",-1)),a(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...e[2]||(e[2]=[t("GOLinux",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[8]||(e[8]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),a(i,{href:"http://linux.cn/"},{default:o(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const E=n(p,[["render",m]]);export{g as __pageData,E as default};
